103	// Run runs the given config, replacing any existing config.
104	func Run(cfg *Config) error {
105		cfgJSON, err := json.Marshal(cfg)
106		if err != nil {
107			return err
108		}
109		return Load(cfgJSON, true)
110	}
111	
112	// Load loads the given config JSON and runs it only
113	// if it is different from the current config or
114	// forceReload is true.
115	func Load(cfgJSON []byte, forceReload bool) error {
116		if err := notify.Reloading(); err != nil {
117			Log().Error("unable to notify service manager of reloading state", zap.Error(err))
118		}
119	
120		// after reload, notify system of success or, if
121		// failure, update with status (error message)
122		var err error
123		defer func() {
124			if err != nil {
125				if notifyErr := notify.Error(err, 0); notifyErr != nil {
126					Log().Error("unable to notify to service manager of reload error",
127						zap.Error(notifyErr),
128						zap.String("reload_err", err.Error()))
129				}
130			}
131			if notifyErr := notify.Ready(); notifyErr != nil {
132				Log().Error("unable to notify to service manager of ready state", zap.Error(notifyErr))
133			}
134		}()
135	
136		err = changeConfig(http.MethodPost, "/"+rawConfigKey, cfgJSON, "", forceReload)
137		if errors.Is(err, errSameConfig) {
138			err = nil // not really an error
139		}
140	
141		return err
142	}
143	
144	// changeConfig changes the current config (rawCfg) according to the
145	// method, traversed via the given path, and uses the given input as
146	// the new value (if applicable; i.e. "DELETE" doesn't have an input).
147	// If the resulting config is the same as the previous, no reload will
148	// occur unless forceReload is true. If the config is unchanged and not
149	// forcefully reloaded, then errConfigUnchanged is returned. This function
150	// is safe for concurrent use.
151	// The ifMatchHeader can optionally be given a string of the format:
152	//
153	//	"<path> <hash>"
154	//
155	// where <path> is the absolute path in the config and <hash> is the expected hash of
156	// the config at that path. If the hash in the ifMatchHeader doesn't match
157	// the hash of the config, then an APIError with status 412 will be returned.
158	func changeConfig(method, path string, input []byte, ifMatchHeader string, forceReload bool) error {
159		switch method {
160		case http.MethodGet,
161			http.MethodHead,
162			http.MethodOptions,
163			http.MethodConnect,
164			http.MethodTrace:
165			return fmt.Errorf("method not allowed")
166		}
167	
168		rawCfgMu.Lock()
169		defer rawCfgMu.Unlock()
170	
171		if ifMatchHeader != "" {
172			// expect the first and last character to be quotes
173			if len(ifMatchHeader) < 2 || ifMatchHeader[0] != '"' || ifMatchHeader[len(ifMatchHeader)-1] != '"' {
174				return APIError{
175					HTTPStatus: http.StatusBadRequest,
176					Err:        fmt.Errorf("malformed If-Match header; expect quoted string"),
177				}
178			}
